import { expect, test } from '../fixtures';

// Starts from the bob session, not the default one.
test.use({ storageState: process.env.SOVA_AUTH_STATE_BOB! });

test('Password same as old', async ({ page }) => {
  await test.step('Open the password settings', async () => {
    await page.goto('/user/settings/password');
  });

  await test.step('Type the old password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('Bob-Pass-123');
  });

  await test.step('Type the new password', async () => {
    await page.getByRole('textbox', { name: 'New password', exact: true }).fill('Bob-Pass-123');
  });

  await test.step('Repeat the new password', async () => {
    await page.getByRole('textbox', { name: 'Confirm new password', exact: true }).fill('Bob-Pass-123');
  });

  await test.step('Press Save', async () => {
    await page.getByRole('button', { name: 'Save', exact: true }).click();
  });

  await test.step('The error says the new password must differ [code]', async () => {
    await expect(page.locator('.invalid-feedback')).toContainText('New password must be different');
  });
});
